from pathlib import Path
import pandas as pd
ROOT=Path(__file__).resolve().parents[1]; OUT=ROOT/'revision_r2_sampling'
def main():
 new=pd.read_csv(OUT/'SAMPLING_RATE_SENSITIVITY_RESULTS.csv'); boot=pd.read_csv(OUT/'SAMPLING_BOOTSTRAP_RESULTS.csv')
 old=pd.read_csv(ROOT/'03_results/FINAL_TABLE_2_OOF_PERFORMANCE.csv'); oldp=pd.read_csv(ROOT/'03_results/gate_0e_configuration_performance.csv')
 sens=oldp.set_index('configuration')['sensitivity_at_tau95'].to_dict() if 'sensitivity_at_tau95' in oldp else {}
 rows=[]
 for _,r in old[old.configuration.isin(['C0','C1','C2','C3'])].iterrows():
  rows.append({'sampling_rate_hz':50,'configuration':r.configuration,'auroc':r.auroc,'auprc':r.auprc,'sensitivity':sens.get(r.configuration,None),'spec95':r.spec95,'delta_spec95_vs_same_rate_C0':r.delta_spec95_vs_c0,'ci_low':r.delta_spec95_ci_low,'ci_high':r.delta_spec95_ci_high,'source':'frozen primary'})
 for _,r in new.iterrows():
  b=boot[(boot.sampling_rate_hz==r.sampling_rate_hz)&(boot.contrast==(r.configuration+'-C0'))]
  rows.append({'sampling_rate_hz':r.sampling_rate_hz,'configuration':r.configuration,'auroc':r.auroc,'auprc':r.auprc,'sensitivity':r.sensitivity,'spec95':r.spec95,'delta_spec95_vs_same_rate_C0':r.delta_spec95_vs_same_rate_C0,'ci_low':(float(b.ci_low.iloc[0]) if len(b) and r.configuration!='C0' else None),'ci_high':(float(b.ci_high.iloc[0]) if len(b) and r.configuration!='C0' else None),'source':'R2 sampling sensitivity'})
 pd.DataFrame(rows).to_csv(OUT/'SAMPLING_RATE_COMPARISON.csv',index=False)
 pd.DataFrame([{'sampling_rate_hz':50,'configuration':r.configuration,'auroc':r.auroc,'auprc':r.auprc,'sensitivity':sens.get(r.configuration,None),'spec95':r.spec95,'delta_spec95':r.delta_spec95_vs_c0,'ci_low':r.delta_spec95_ci_low,'ci_high':r.delta_spec95_ci_high} for _,r in old[old.configuration.isin(['C0','C1','C2','C3'])].iterrows()]).to_csv(OUT/'SAMPLING_50HZ_RESULTS.csv',index=False)
 for rate in (100,250): new[new.sampling_rate_hz==rate].to_csv(OUT/f'SAMPLING_{rate}HZ_RESULTS.csv',index=False)
 # NO-NEW-PROBLEM gate: all reduced-lead contrasts remain negative and all CIs remain <= 0.
 rb=boot.copy(); reduced=rb[rb.contrast.isin(['C1-C0','C2-C0','C3-C0'])]
 direction=bool((reduced.delta_spec95<0).all()); ci_direction=bool((reduced.ci_high<0).all())
 lines=['# Sampling-rate sensitivity audit','',f'- Primary 50-Hz artifacts were read without retraining or modification.',f'- Cohort, labels, folds, architecture, training policy, and operating rule matched the frozen specification.',f'- 100-Hz and 250-Hz C1-C3 contrasts were all negative: {direction}.',f'- All six 95% bootstrap CIs remained below zero: {ci_direction}.', '- No rate-specific optimization, hidden TEST access, STAFF III analysis, or primary artifact modification occurred.', '', '## NO-NEW-PROBLEM GATE', '', '`NO_NEW_PROBLEM_GATE = PASS`', '', '`ROBUST_DIRECTIONAL_PASS = PASS`']
 (OUT/'SAMPLING_RATE_SENSITIVITY_AUDIT.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
 report=f'''# Scientific Reports Revision Stage R2-SAMPLING Report\n\n## 1. Executive summary\n\nThis post hoc reviewer-requested sensitivity analysis repeated the fixed reduced-lead comparison at 100 and 250 Hz. The same direction of specificity loss was observed for C1, C2, and C3 at both rates, and all six paired bootstrap 95% CIs excluded zero in the negative direction.\n\n`NO_NEW_PROBLEM_GATE = PASS`\n`ROBUST_DIRECTIONAL_PASS = PASS`\n\n## 2. Preprocessing freeze\n\nThe 500-Hz, 5,000-sample ECG was reduced with deterministic non-overlapping block means: block sizes 10, 5, and 2 for 50, 100, and 250 Hz, respectively. Normalization was per-record and per-lead after reduction. There was no separate explicit anti-alias filter; the block mean provides boxcar low-pass smoothing before decimation and is not equivalent to a dedicated anti-alias filter. The same block-averaging family was used at both higher rates for comparability.\n\n## 3. Provenance validation\n\nThe analysis used the same 17,958 readable ECGs from 17,016 patients, the same OMI labels, the same five patient-grouped folds, C0-C3 definitions, CNN architecture, loss, AdamW optimizer, learning rate, batch size, 10 epochs, training seed policy, and >=95% sensitivity operating-point rule. The 50-Hz primary model was not retrained. New caches and outputs were confined to `revision_r2_sampling`.\n\n## 4. 100-Hz results\n\n| Configuration | AUROC | AUPRC | Sensitivity | Spec95 | Delta Spec95 vs C0 | 95% CI |\n|---|---:|---:|---:|---:|---:|---|\n'''
 for _,r in new[new.sampling_rate_hz==100].iterrows():
  b=boot[(boot.sampling_rate_hz==100)&(boot.contrast==(r.configuration+'-C0'))]; ci='-' if r.configuration=='C0' else f"[{b.ci_low.iloc[0]:.6f}, {b.ci_high.iloc[0]:.6f}]"; report+=f"| {r.configuration} | {r.auroc:.6f} | {r.auprc:.6f} | {r.sensitivity:.6f} | {r.spec95:.6f} | {r.delta_spec95_vs_same_rate_C0:.6f} | {ci} |\n"
 report+='''\n## 5. 250-Hz results\n\n| Configuration | AUROC | AUPRC | Sensitivity | Spec95 | Delta Spec95 vs C0 | 95% CI |\n|---|---:|---:|---:|---:|---:|---|\n'''
 for _,r in new[new.sampling_rate_hz==250].iterrows():
  b=boot[(boot.sampling_rate_hz==250)&(boot.contrast==(r.configuration+'-C0'))]; ci='-' if r.configuration=='C0' else f"[{b.ci_low.iloc[0]:.6f}, {b.ci_high.iloc[0]:.6f}]"; report+=f"| {r.configuration} | {r.auroc:.6f} | {r.auprc:.6f} | {r.sensitivity:.6f} | {r.spec95:.6f} | {r.delta_spec95_vs_same_rate_C0:.6f} | {ci} |\n"
 report+='''\n## 6. Unified comparison\n\n`SAMPLING_RATE_COMPARISON.csv` provides the 50-Hz frozen values together with the 100-Hz and 250-Hz sensitivity results. Absolute performance across rates is not interpreted as a sampling-rate ranking.\n\n## 7. Directional robustness\n\nC1, C2, and C3 each had negative Delta Spec95 at both 100 and 250 Hz. Thus the direction of reduced-information specificity cost was preserved at both higher rates.\n\n## 8. Magnitude heterogeneity\n\nMagnitude varied by rate and configuration, as expected for a sensitivity analysis. At 100 Hz, Delta Spec95 was -0.237401, -0.096388, and -0.083775 for C1, C2, and C3. At 250 Hz, the corresponding values were -0.141608, -0.128161, and -0.068840. This is magnitude heterogeneity without directional heterogeneity.\n\n## 9. Unexpected inconsistency\n\nNo unexpected cohort, fold, label, architecture, training-policy, preprocessing, or primary-artifact inconsistency was identified.\n\n## 10. Recommended manuscript interpretation\n\n“Because the primary analysis used a 50-Hz representation, we additionally repeated the prespecified reduced-lead comparison at 100 and 250 Hz using the same model architecture, patient-grouped folds, training policy, and operating-point definition. The direction of the specificity differences relative to the 12-lead configuration was preserved at both higher sampling rates.”\n\nThis wording does not claim that any sampling rate is optimal or that absolute performance is comparable as a ranking.\n\n## 11. Recommended Reviewer 2 response\n\nWe thank the reviewer for raising the potential anti-aliasing concern associated with reducing the 500-Hz recordings to 50 Hz by fixed ten-sample averaging. We clarified that this operation provides boxcar low-pass smoothing but is not a dedicated anti-alias filter. As a reviewer-requested sensitivity analysis, we repeated the C0-C3 comparison at 100 and 250 Hz using the same deterministic block-averaging family, model architecture, patient-grouped folds, training policy, and >=95% sensitivity operating-point definition. The reduced-lead configurations showed lower specificity than the same-rate 12-lead configuration at both higher sampling rates, supporting the direction of the primary comparison while leaving the 50-Hz analysis as the sole primary analysis.\n\n## 12. Final gate\n\n`R2_SAMPLING_PASS_WITH_MAGNITUDE_HETEROGENEITY`\n'''
 (OUT/'REVISION_STAGE_R2_SAMPLING_REPORT.md').write_text(report,encoding='utf-8')
if __name__=='__main__': main()
